return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'uz_UZ','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-09-26T12:05:05+00:00','po-revision-date'=>'2026-09-26T12:05:05+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'Qayta qurilgan Page Builder Sandwich-ning asosiy relizi: sozlamalar va "Haqida" ekrani, qidiruv tizimi izlaridan xoli old qism chiquvchi qatlami va bitta namuna tarkib bloki.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'AI provayderlari','The makers of ChatGPT. A good all-rounder.'=>'ChatGPT yaratuvchilari. Yaxshi universal yordamchi.','The makers of Claude. Strong at writing and careful reasoning.'=>'Claude yaratuvchilari. Matn yozish va puxta fikrlashda kuchli.','Google\'s Gemini models. Fast and inexpensive.'=>'Google\'s Gemini modellari. Tez va hamyonbop.','A European AI company with fast, inexpensive models.'=>'Tez va arzon modellarga ega Yevropa sun\'iy intellekt kompaniyasi.','Low-cost models that are good at writing and code.'=>'Yozish va kod yozishda yaxshi bo\'lgan arzon modellar.','One key for models from many different providers.'=>'Ko\'pgina turli provayderlardagi modellar uchun bitta kalit.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'OpenAI API kabi ishlaydigan har qanday xizmat, jumladan, o\'z kompyuteringiz yoki serveringizda ishlaydigan model.','General (used when nothing more specific is set)'=>'Umumiy (aniqroq sozlama ko\'rsatilmaganda qo\'llaniladi)','Writing and rewriting'=>'Yozish va qayta yozish','Translation'=>'Tarjima','Code and CSS'=>'Kod va CSS','Sorry, you are not allowed to access this page.'=>'Kechirasiz, bu sahifaga kirishga ruxsat berilmagan.','These settings are shared by every plugin that uses them: %s.'=>'Bu sozlamalar ulardan foydalanadigan har bir plagin tomonidan umumiy foydalaniladi: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Kalitlaringiz ushbu sayt maʼlumotlar bazasida shifrlangan boʻlib, ular hech qachon bizga emas, faqat siz tanlagan provayderga yuboriladi.','Step 1 of 2: choose an AI provider'=>'1-qadam (jami 2 ta): sun\'iy intellekt provayderini tanlang','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Oʻzingizning kalitingizdan foydalanasiz, shuning uchun foydalanganingiz uchun toʻlovni toʻgʻridan-toʻgʻri provayderga amalga oshirasiz. Ishonchingiz komil emasmi? Bularning har biri yaxshi ishlaydi; keyinchalik yana qoʻshishingiz mumkin.','Next'=>'Keyingi','Step 2 of 2: connect %s'=>'2-qadam: %s ni ulang','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'/v1 bilan tugaydigan OpenAI bilan mos keluvchi xizmatingiz manzilini kiriting. Kalit faqat xizmat uni talab qilgandagina kerak bo\'ladi.','Open %s and sign in (or create a free account).'=>'%s ni oching va tizimga kiring (yoki bepul hisob yarating).','the %s API keys page'=>'%s API kalitlari sahifasi','Create a new key and copy it.'=>'Yangi kalit yarating va uni nusxalang.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Uni quyiga qo\'ying va "Saqlash va sinovdan o\'tkazish" tugmasini bosing. Uning ishlashini tekshirish uchun biz bitta kichik so\'rov yuboramiz.','Most providers need a little credit on the account before a key works: %s.'=>'Ko\'pchlik provayderlar kalit ishlashi uchun hisobda ozgina mablag\' talab qiladi: %s.','add credit'=>'kredit qo\'shish','← Choose a different provider'=>'← Boshqa provayderni tanlang','Address'=>'Manzil','Saved key ends in …%s — paste a new one to replace it'=>'Saqlangan kalit …%s bilan tugaydi — uni almashtirish uchun yangisini qo‘ying','Key (optional)'=>'Kalit (ixtiyoriy)','API key'=>'API kaliti','Save and test'=>'Saqlash va sinovdan o\'tkazish','Providers'=>'Provayderlar','Provider'=>'Provayder','Status'=>'Status','Key'=>'Kalit','Get a key'=>'Kalit olish','Test'=>'Sinov','Remove'=>'Olib tashlash','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Yangiroq plagin versiyasi tomonidan saqlangan: ushbu plaginni yangilang yoki kalitni qaytadan kiriting.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Saqlangan kalitni endi ochib bo‘lmaydi (saytning xavfsizlik kalitlari o‘zgargan). Uni qaytadan kiriting.','Not connected'=>'Ulanmagan','Connected — last test passed %s'=>'Ulangan — oxirgi sinovdan o\'tdi %s','Last test failed: %s'=>'Oxirgi sinov muvaffaqiyatsiz tugadi: %s','Connected — not tested yet'=>'Ulangan — hali sinovdan o‘tkazilmagan','Which model to use'=>'Qaysi modeldan foydalanish kerak','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ ushbu vazifa uchun tavsiyamizni bildiradi. Roʻyxatda kalitingiz foydalanishi mumkin boʻlgan barcha modellar provayderdagi maʼlumotlarga asoslangan holda keltirilgan.','— Recommended for the provider —'=>'— Provayder uchun tavsiya etiladi —','Save models'=>'Modellarni saqlash','Refresh the model lists from the providers'=>'Ta\'minotchilardan model ro\'yxatlarini yangilash','best quality'=>'eng yaxshi sifat','lowest cost'=>'eng past narx','fastest'=>'eng tezkor','Add a model yourself'=>'Modelni o\'zingiz qo\'shing','A model came out today? Paste its exact name to use it straight away.'=>'Bugun yangi model chiqdimi? Undan darhol foydalanish uchun uning aniq nomini kiriting.','Model name'=>'Model nomi','Add model'=>'Model qo‘shish','Recommended models list'=>'Tavsi etilgan modellar roʻyxati','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Tavsiya etilgan modellar roʻyxatini tekshirib boʻlmadi, shuning uchun hech qanday tavsiya koʻrsatilmagan. Plaginni qayta oʻrnating yoki quyida kundalik yangilanishlarni yoqing.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Foydalanilayotgan roʻyxat %s da eʼlon qilingan. Har bir plagin yangilanishi yangisini olib keladi.','Also check Zinn Digital® once a day for an updated list.'=>'Yangilangan ro‘yxat uchun Zinn Digital® saytini kuniga bir marta tekshirib turing.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Faqat oddiy yuklab olish soʻrovi yuboriladi: kalit ham, sayt manzili ham, kontentingiz haqida hech narsa ham yoʻq. Roʻyxat imzolanadi va imzoni tekshiruvdan oʻta olmagan roʻyxat eʼtiborga olinmaydi.','Last checked %1$s: %2$s.'=>'Oxirgi marta tekshirilgan vaqt %1$s: %2$s.','Save, and check now if turned on'=>'Saqlang va agar yoqilgan bo\'lsa, hoziroq tekshiring','a newer list was installed'=>'yangiroq roʻyxat oʻrnatildi','already up to date'=>'allaqachon yangilangan','the download failed the signature check and was ignored'=>'yuklab olish imzo tekshiruvidan o‘tmadi va e’tiborga olinmadi','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® bilan bog‘lanib bo‘lmadi; joriy ro‘yxat ishlatilishda davom etadi','turned off'=>'o‘chirilgan','Open'=>'Ochish','Check their status page'=>'Ularning holat sahifasini tekshiring','Open your billing page'=>'Hisob-kitob sahifangizni oching','Open your API keys page'=>'API kalitlari sahifasini oching','Open the AI settings'=>'AI sozlamalarini ochish','Sorry, you are not allowed to do that.'=>'Kechirasiz, buni qilishga ruxsatingiz yo\'q.','Unknown provider.'=>'Nomaʼlum provayder.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Xizmatingiz manzilini kiriting, masalan, http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Bu API kalitiga o\'xshamaydi. Uni probelsiz holda qaytadan nusxalang.','Paste your API key first.'=>'Avval API kalitingizni qo\'ying.','Key removed.'=>'Kalit olib tashlandi.','Models saved.'=>'Modellar saqlandi.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Modelning aniq nomini kiriting, masalan, provayder hujjatlarida yozilganidek.','Added %s. Choose it under "Which model to use".'=>'%s qo\'shildi. Uni "Qaysi modeldan foydalanish" ostidan tanlang.','Model removed.'=>'Model olib tashlandi.','Daily updates are off. The list that came with the plugin is used.'=>'Kunlik yangilanishlar oʻchirilgan. Plagin bilan birga kelgan roʻyxat ishlatiladi.','Checked: %s.'=>'Tekshirildi: %s.','Model lists refreshed.'=>'Model roʻyxatlari yangilandi.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Sizning AI kalitingiz plaginlaringizdan birining yangiroq versiyasi tomonidan saqlangan. Ushbu plaginni yangilang yoki AI sozlamalarida kalitni qaytadan kiriting.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Saqlangan sunʼiy intellekt kalitingizni endi ochib boʻlmaydi (saytning xavfsizlik kalitlari oʻzgargan). Uni sunʼiy intellekt sozlamalarida qaytadan kiriting.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI hali sozlangan emas. AI sozlamalarida AI provayderi uchun kalit qo\'shing.','No model is chosen for this task. Pick one in the AI settings.'=>'Bu vazifa uchun hech qanday model tanlanmagan. Sun\'iy intellekt sozlamalaridan birini tanlang.','That AI provider is not supported by this version of the plugin.'=>'Ushbu sun\'iy intellekt provayderi plaginning ushbu versiyasi tomonidan qo\'llab-quvvatlanmaydi.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Ushbu sayt sun\'iy intellekt xizmatingizga ulanolmadi. U ishlayotganini va uning manziliga veb-serveringizdan ulanish mumkinligini tekshiring (shaxsiy kompyuteringizdagi xizmatga xostingdagi saytdan ulanib bo‘lmaydi).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Bu sayt %s manziliga ulanib bo\'lmadi. Uning holat sahifasini tekshiring; agar u ishlayotgan bo\'lsa, xostingiz chiquvchi ulanishlarni bloklayotgan bo\'lishi mumkin yoki manzil noto\'g\'ri.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s hisobingizda mablag‘ yoki kvota qolmaganini bildiradi. Ularning hisobingizdagi mablag‘ni to‘ldiring yoki limitni oshiring, so‘ngra qaytadan urinib ko‘ring.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s kalitingizni qabul qilmadi. U xato kiritilgan, bekor qilingan yoki muddati tugagan bo\'lishi mumkin. Yangi kalit yarating va uni shu yerga qo\'ying.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s kalitingiz uchun qilingan ushbu so‘rovni rad etdi. Kalit bu model yoki funksiyaga kirish huquqiga ega bo‘lmasligi mumkin yoxud hisobingizni tasdiqlash talab etiladi.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Kalitingiz uchun %2$s dan "%1$s" modeli mavjud emas. AI sozlamalaridan boshqa modelni tanlang.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Sizning %2$s rejangiz "%1$s" modelini o\'z ichiga olmaydi. AI sozlamalarida boshqa modelni tanlang yoki rejangizni ular bilan yangilang.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s kalitingiz soʻrovlarni yuborish tezligini cheklamoqda. Bir daqiqa kuting va qayta urinib koʻring yoki ular bilan limitni oshiring.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s da hozirda muammolar mavjud (ularning tomonidan nosozlik yoki ortiqcha yuklanish). Sozlamalaringizda hech qanday xatolik yo\'q. Birozdan keyin yana urinib ko\'ring.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Sun\'iy intellekt so\'rovi biz aniqlay olmagan sababga ko\'ra bajarilmadi. Qaytadan urinib ko\'ring; agar bu holat takrorlanaversa, quyidagi tafsilotlar bilan qo\'llab-quvvatlash xizmatiga murojaat qiling.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Sun\'iy intellekt provayderi ushbu plagin o\'qiy olmaydigan shaklda javob berdi. Qaytadan urinib ko\'ring; agar bu holat takrorlanaversa, boshqa modelni tanlang yoki qo\'llab-quvvatlash xizmatiga murojaat qiling.','Custom (OpenAI-compatible)'=>'Maxsus (OpenAI-mos)','Save a key for this provider first.'=>'Avval ushbu provayder uchun kalitni saqlang.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Kalitingiz ishlayapti, biroq provayder unda matn modeli mavjud emasligini ko‘rsatmoqda. Quyida o‘zingiz model qo‘shing.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Ulandi. %1$s %2$s yordamida javob berdi. Sun\'iy intellekt funksiyalaringiz foydalanishga tayyor.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Sizning foydalanuvchi rolingizga ushbu saytda sun\'iy intellektdan foydalanishga ruxsat etilmagan. Administratorga murojaat qiling.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Bu sayt oylik sun\'iy intellekt xarajatlari limitiga yetdi. Administrator buni sun\'iy intellekt sozlamalarida oshirishi mumkin.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Bu sayt sun\'iy intellekt so\'rovlarining oylik limitiga yetdi. Administrator buni sun\'iy intellekt sozlamalarida oshirishi mumkin.','Usage and cost'=>'Foydalanish va narx','The log, limits and role permissions apply to AI used through: %s.'=>'Жurnal, cheklashlar va rol ruxsatlari quyidagi orqali ishlatiladigan sun\'iy intellektga nisbatan qo\'llaniladi: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Xarajatlar taxminiy bo\'lib, e\'lon qilingan narxlardan kelib chiqqan holda hisoblangan; narxi noma\'lum bo\'lgan model nolga teng deb olinadi.','This month: %1$s requests, about %2$s.'=>'Bu oy: %1$s soʻrov, taxminan %2$s.','When'=>'Qachon','Who'=>'Kim','Used for'=>'Foydalanilgan','Model'=>'Model','Tokens in / out'=>'Kiruvchi / chiquvchi tokenlar','About'=>'Haqida','Result'=>'Natija','No AI requests have been made yet.'=>'Hozircha hech qanday sun\'iy intellekt so\'rovlari yuborilmagan.','Done'=>'Bajarildi','Limits and permissions'=>'Chegaralar va ruxsatlar','Monthly spending limit (US dollars)'=>'Oylik xarajatlar limiti (US dollar)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Cheklov bo\'lmasa, bo\'sh qoldiring. Taxminiy xarajat unga yetgandan so\'ng, sun\'iy intellekt oyning qolgan qismi uchun to\'xtaydi.','Monthly request limit'=>'Oylik so\'rovlar limiti','Leave empty for no limit.'=>'Cheklanmagan qoldirish uchun bo\'sh qoldiring.','Who may use AI'=>'Sun\'iy intellektdan kimlar foydalanishi mumkin','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Plagin funksiyalaridan foydalana oladigan har bir kishi sun\'iy intellektni ishlatishiga ruxsat berish uchun hech birini belimang. Administratorlar undan doimiy ravishda foydalana oladilar.','Save limits and permissions'=>'Cheklovlar va ruxsatlarni saqlash','Limits and permissions saved.'=>'Chegaralar va ruxsatlar saqlandi.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'PlaginningUshbu nusxasidagi admin ekranining skriptlari yetishmayapti. Uni chiqarilgan paketdan qaytadan o\'rnating.','This screen needs JavaScript.'=>'Ushbu ekran uchun JavaScript talab qilinadi.','Languages'=>'Tillar','Upgrade'=>'Yangilash','Pricing'=>'Narxlar','Start Trial'=>'Sinov muddatini boshlash','Account'=>'Hisob','Contact Us'=>'Biz bilan bog‘laning','Affiliation'=>'Hamkorlik','the kind of softwarePlugin'=>'Plagin','greetingHey %s,'=>'Salom %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Xavfsizlik va funksiyalar yangilanishlari, o‘quv qo‘llanmalari va vaqti-vaqti bilan taqdim etiladigan takliflar bo‘yicha elektron pochta xabarnomalarini olish hamda asosiy WordPress muhiti ma\'lumotlarini ulashish uchun ro‘yxatdan o‘ting. Bu bizga %s ni saytingizga moslashuvchanroq qilishga va sizga kerakli vazifalarni yanada yaxshiroq bajarishiga yordam beradi.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Xavfsizlik va funksiya yangilanishlari, oʻquv materiallari hamda vaqti-vaqti bilan taqdim etiladigan takliflar boʻyicha elektron pochta xabarnomalarini olish hamda asosiy WordPress muhiti haqida baʼzi maʼlumotlarni ulashish uchun roʻyxatdan oʻting.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Buni o\'tkazib yuborsangiz ham muammo yo\'q! %1$s baribir yaxshi ishlayveradi.','Allow & Continue'=>'Ruxsat berish va davom etish','verbSkip'=>'O‘tkazib yuborish','Skipping, please wait'=>'O‘tkazib yuborilmoqda, iltimos kuting','Continue'=>'Davom etish','Please wait'=>'Iltimos, kuting','as activating pluginActivating'=>'Faollashtirilmoqda','This will allow %s to'=>'Bu %s ga quyidagilarga ruxsat beradi','Privacy Policy'=>'Maxfiylik siyosati','Terms of Service'=>'Foydalanish shartlari','License Agreement'=>'Litsenziya shartnomasi','Have a license key?'=>'Litsenziya kalitingiz bormi?','Activate License'=>'Litsenziyani faollashtirish','View Basic Profile Info'=>'Asosiy profil ma\'lumotlarini ko\'rish','Your WordPress user\'s: first & last name, and email address'=>'Sizning WordPress foydalanuvchingiz: ismi va familiyasi hamda elektron pochta manzili','View Basic Website Info'=>'Asosiy veb-sayt ma\'lumotlarini ko\'rish','Homepage URL & title, WP & PHP versions, and site language'=>'Bosh sahifa URL manzili va sarlavhasi, WP va PHP versiyalari hamda sayt tili','View Basic %s Info'=>'Asosiy %s maʼlumotlarini koʻrish','Current %s & SDK versions, and if active or uninstalled'=>'Joriy %s & SDK versiyalari, shuningdek ular faol yoki o\'chirilgani','Newsletter'=>'Axborotnoma','Updates, announcements, marketing, no spam'=>'Yangilanishlar, e\'lonlar, marketing, spam yo\'q','View Diagnostic Info'=>'Tashxis ma\'lumotlarini ko\'rish','WordPress & PHP versions, site language & title'=>'WordPress va PHP versiyalari, sayt tili va sarlavhasi','View Plugins & Themes List'=>'Plaginlar va mavzular ro\'yxatini ko\'rish','Names, slugs, versions, and if active or not'=>'Nomlar, sluglar, versiyalar va faol yoki faol emasligi','optional'=>'ixtiyoriy','Never miss an important update'=>'Muhim yangilanishni hech qachon o\'tkazib yubormang','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Muhim yangilanishni o‘tkazib yubormasligingiz va %s ni saytingizga moslashuvchanroq hamda siz xohlagan vazifalarni bajarishda samaraliroq qilishimizga yordam berish uchun ushbu ixtiyoriy funksiyani joriy qildik.','Thank you for updating to %1$s v%2$s!'=>'%1$s v%2$s ga yangilaganingiz uchun tashakkur!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Prefiks 1 dan 8 gacha kichik harflar yoki raqamlardan iborat bo\'lishi, harf bilan boshlanishi va plagin nomiga teng bo\'lmasligi kerak.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Zinn Digital® Ltd kompaniyasi bosh direktori Neil Lock tomonidan yaratilgan','Version %s'=>'Versiya %s','Page Builder Sandwich website'=>'Page Builder Sandwich veb-sayti','Zinn Digital® website'=>'Zinn Digital® veb-sayti','Settings saved.'=>'Sozlamalar saqlandi.','See the Pro plans and pricing'=>'Pro rejalar va narxlarni ko\'rish','Front-end output'=>'Old tomon chiqishi','Class name prefix'=>'Sinf nomi prefiksi','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Plagin sahifalaringizda chop etadigan har bir klass nomi ushbu prefiks bilan boshlanadi, shuning uchun sahifalar qaysi plagin tomonidan yaratilganini oshkor qilmaydi. Harf bilan boshlanadigan 1 dan 8 gacha kichik harflar yoki raqamlar.','Save'=>'Saqlash','Beta updates'=>'Beta yangilanishlar','This site receives beta versions as updates.'=>'Ushbu sayt yangilanish sifatida beta-versiyalarni qabul qiladi.','This site receives stable versions only.'=>'Bu saytga faqat barqaror versiyalar qabul qilinadi.','Change this on the Account page'=>'Buni Hisob sahifasida o\'zgartiring','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Beta versiyalar o\'z hisobiga ulangan litsenziyaga ega Pro o\'rnatishlariga taqdim etiladi. Ulangandan so\'ng, Hisob sahifasidan qo\'shilishingiz mumkin.','Content'=>'Kontent','Heading'=>'Sarlavha','Text'=>'Matn','Style'=>'Uslub','Plain'=>'Oddiy','Accent'=>'Aksent','No languages to switch between. The switcher appears when a translation plugin lists two or more languages.'=>'Almashtirish uchun tillar mavjud emas. Almashtirgich tarjima plagini ikkita yoki undan ortiq tilni ko‘rsatganda paydo bo‘ladi.','Switcher'=>'O‘tkazgich','Accessible label'=>'Ochiq yorliq','Show the current language'=>'Joriy tilni ko\'rsatish','block titleLanguage switcher (sample)'=>'Tilni almashtirgich (namuna)','block descriptionLists the site\'s languages from the translation plugin, when one is active. It renders nothing otherwise.'=>'Tarjima Plagini faol bo‘lganda sayt tillarini ro‘yxat ko‘rinishida chiqaradi, aks holda hech narsa ko‘rsatmaydi.','block keywordlanguage'=>'Til','block keywordswitcher'=>'almashtirgich','block titleSample content'=>'Namuna tarkib','block descriptionA heading and a paragraph, rendered with neutral class names. It is the reference block for the translation contract.'=>'Neytral sinf nomlari bilan render qilingan sarlavha va paragraf. Bu tarjima shartnomasi uchun ma\'lumotnoma bloki.','block keywordsample'=>'namuna','block keywordtext'=>'matn']];